/** pairs that import each other */
function mutualPairs(edges) {
  // Write your solution here
  const out = [];
  for (const [a, b] of edges) if (edges.some(([x, y]) => x === b && y === a)) out.push(a + ' <-> ' + b);
  return out;
}

