// Reference solution
function mutualPairs(edges) {
  const set = new Set(edges.map(([a, b]) => `${a}\u0000${b}`));
  const out = new Set();
  for (const [a, b] of edges) {
    if (a !== b && set.has(`${b}\u0000${a}`)) out.add(a < b ? `${a} <-> ${b}` : `${b} <-> ${a}`);   // mỗi cặp một lần, tên nhỏ trước
  }
  return [...out].sort();
}

