/** all import cycles */
function findCycles(edges) {
  // Write your solution here — finds only 2-module cycles
  const out = [];
  for (const [a, b] of edges) if (a < b && edges.some(([x, y]) => x === b && y === a)) out.push([a, b]);
  return out;
}

